#ifndef FILEUTIL_COMMON_H
#define FILEUTIL_COMMON_H
#define _GNU_SOURCE
#include <sys/stat.h>
#include <stdbool.h>
#include <stddef.h>

extern const char *program;
void init_program(const char *argv0);
void error_path(const char *operation, const char *path);
void *xmalloc(size_t size);
char *xstrdup(const char *s);
char *join_path(const char *left, const char *right);
const char *base_name(const char *path);
char *clean_path(const char *path);
bool confirm(const char *operation, const char *path);
int remove_tree(const char *path, bool recursive, bool dirs, bool force,
                bool interactive, bool verbose);
int copy_tree(const char *source, const char *target);
int parse_mode(const char *text, mode_t *mode);
#endif
#include "common.h"
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

const char *program = "fileutils";

void init_program(const char *argv0) { program = base_name(argv0); }
const char *base_name(const char *path) {
    const char *slash = strrchr(path, '/');
    return slash ? slash + 1 : path;
}
void error_path(const char *operation, const char *path) {
    int saved = errno;
    fprintf(stderr, "%s: %s '%s': %s\n", program, operation, path, strerror(saved));
}
void *xmalloc(size_t size) {
    void *p = malloc(size ? size : 1);
    if (!p) { perror(program); exit(1); }
    return p;
}
char *xstrdup(const char *s) {
    char *p = xmalloc(strlen(s) + 1);
    strcpy(p, s);
    return p;
}
char *join_path(const char *left, const char *right) {
    size_t n = strlen(left), m = strlen(right);
    char *p = xmalloc(n + m + 2);
    memcpy(p, left, n);
    if (n && left[n - 1] != '/') p[n++] = '/';
    memcpy(p + n, right, m + 1);
    return p;
}
char *clean_path(const char *path) {
    char *p = xstrdup(path);
    size_t n = strlen(p);
    while (n > 1 && p[n - 1] == '/') p[--n] = '\0';
    return p;
}
bool confirm(const char *operation, const char *path) {
    fprintf(stderr, "%s: %s '%s'? ", program, operation, path);
    fflush(stderr);
    int c = getchar(), first = c;
    while (c != '\n' && c != EOF) c = getchar();
    return first == 'y' || first == 'Y';
}
int parse_mode(const char *text, mode_t *mode) {
    char *end;
    errno = 0;
    unsigned long n = strtoul(text, &end, 8);
    if (!*text || *text == '-' || *end || errno || n > 07777) return -1;
    *mode = (mode_t)n;
    return 0;
}

/* lstat is deliberate: removing a directory symlink removes only the link. */
int remove_tree(const char *path, bool recursive, bool dirs, bool force,
                bool interactive, bool verbose) {
    struct stat st;
    if (lstat(path, &st) < 0) {
        if (force && errno == ENOENT) return 0;
        error_path("cannot access", path); return -1;
    }
    if (S_ISDIR(st.st_mode)) {
        if (!recursive && !dirs) {
            errno = EISDIR; error_path("cannot remove", path); return -1;
        }
        if (recursive) {
            if (interactive && !confirm("descend into directory", path)) return 1;
            DIR *dir = opendir(path);
            if (!dir) { error_path("cannot open directory", path); return -1; }
            int failed = 0, skipped = 0;
            struct dirent *entry;
            for (;;) {
                errno = 0;
                entry = readdir(dir);
                if (!entry) {
                    if (errno) { error_path("cannot read directory", path); failed = 1; }
                    break;
                }
                if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
                char *child = join_path(path, entry->d_name);
                int rc = remove_tree(child, true, dirs, force, interactive, verbose);
                if (rc < 0) failed = 1;
                if (rc > 0) skipped = 1;
                free(child);
            }
            if (closedir(dir) < 0) { error_path("cannot close directory", path); failed = 1; }
            if (failed) return -1;
            if (skipped) return 1;
        }
    }
    if (interactive && !confirm("remove", path)) return 1;
    int rc = S_ISDIR(st.st_mode) ? rmdir(path) : unlink(path);
    if (rc < 0) { error_path("cannot remove", path); return -1; }
    if (verbose) printf("removed '%s'\n", path);
    return 0;
}

/* Cross-filesystem mv fallback. Never traverse symbolic links. */
int copy_tree(const char *source, const char *target) {
    struct stat st;
    if (lstat(source, &st) < 0) { error_path("cannot stat", source); return -1; }
    if (S_ISLNK(st.st_mode)) {
        size_t size = st.st_size > 0 ? (size_t)st.st_size + 1 : 256;
        char *link;
        for (;;) {
            link = xmalloc(size + 1);
            ssize_t n = readlink(source, link, size);
            if (n < 0) { error_path("cannot read link", source); free(link); return -1; }
            if ((size_t)n < size) { link[n] = '\0'; break; }
            free(link); size *= 2;
        }
        int rc = symlink(link, target);
        free(link);
        if (rc < 0) { error_path("cannot create link", target); return -1; }
        struct timespec times[2] = { st.st_atim, st.st_mtim };
        if (utimensat(AT_FDCWD, target, times, AT_SYMLINK_NOFOLLOW) < 0) {
            error_path("cannot set timestamps", target); return -1;
        }
        return 0;
    }
    if (S_ISDIR(st.st_mode)) {
        if (mkdir(target, 0700) < 0) { error_path("cannot create directory", target); return -1; }
        DIR *dir = opendir(source);
        if (!dir) { error_path("cannot open directory", source); return -1; }
        int failed = 0;
        for (;;) {
            errno = 0;
            struct dirent *entry = readdir(dir);
            if (!entry) {
                if (errno) { error_path("cannot read directory", source); failed = 1; }
                break;
            }
            if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
            char *src = join_path(source, entry->d_name);
            char *dst = join_path(target, entry->d_name);
            if (copy_tree(src, dst) < 0) failed = 1;
            free(src); free(dst);
            if (failed) break;
        }
        if (closedir(dir) < 0) { error_path("cannot close directory", source); failed = 1; }
        if (failed) return -1;
    } else if (S_ISREG(st.st_mode)) {
        int in = open(source, O_RDONLY | O_NOFOLLOW);
        if (in < 0) { error_path("cannot open", source); return -1; }
        int out = open(target, O_WRONLY | O_CREAT | O_EXCL, 0600);
        if (out < 0) { error_path("cannot create", target); close(in); return -1; }
        char buffer[65536];
        int failed = 0;
        for (;;) {
            ssize_t n = read(in, buffer, sizeof buffer);
            if (n < 0 && errno == EINTR) continue;
            if (n < 0) { error_path("cannot read", source); failed = 1; break; }
            if (!n) break;
            for (ssize_t offset = 0; offset < n;) {
                ssize_t written = write(out, buffer + offset, (size_t)(n - offset));
                if (written < 0 && errno == EINTR) continue;
                if (written <= 0) { error_path("cannot write", target); failed = 1; break; }
                offset += written;
            }
            if (failed) break;
        }
        if (close(in) < 0) { error_path("cannot close", source); failed = 1; }
        if (close(out) < 0) { error_path("cannot close", target); failed = 1; }
        if (failed) return -1;
    } else {
        errno = ENOTSUP; error_path("cannot copy special file", source); return -1;
    }
    if (chmod(target, st.st_mode & 07777) < 0) { error_path("cannot set mode", target); return -1; }
    struct timespec times[2] = { st.st_atim, st.st_mtim };
    if (utimensat(AT_FDCWD, target, times, 0) < 0) {
        error_path("cannot set timestamps", target); return -1;
    }
    return 0;
}
#include "common.h"
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static void usage(void) {
    printf("Usage: %s [-acmh] [-r REFERENCE | -t YYYYMMDDhhmm[.ss]] FILE...\n"
           "Update access and modification times; create absent files unless -c.\n"
           "  -a access only  -m modification only  -h affect symlink itself\n", program);
}
static int timestamp(const char *s, struct timespec *out) {
    size_t length = strlen(s);
    if (length != 12 && length != 15) return -1;
    for (size_t i = 0; i < length; ++i) {
        if (i == 12) { if (s[i] != '.') return -1; }
        else if (s[i] < '0' || s[i] > '9') return -1;
    }
    struct tm tm = {0};
    char *end = strptime(s, "%Y%m%d%H%M", &tm);
    if (!end) return -1;
    if (*end == '.') {
        char *next;
        long sec = strtol(end + 1, &next, 10);
        if (next != end + 3 || *next || sec < 0 || sec > 59) return -1;
        tm.tm_sec = (int)sec;
    } else if (*end) return -1;
    struct tm requested = tm;
    tm.tm_isdst = -1;
    time_t t = mktime(&tm);
    if (tm.tm_year != requested.tm_year || tm.tm_mon != requested.tm_mon ||
        tm.tm_mday != requested.tm_mday || tm.tm_hour != requested.tm_hour ||
        tm.tm_min != requested.tm_min) return -1;
    out->tv_sec = t; out->tv_nsec = 0;
    return 0;
}
int main(int argc, char **argv) {
    init_program(argv[0]);
    bool access_only = false, modify_only = false, no_create = false, no_follow = false;
    const char *reference = NULL, *stamp = NULL;
    const struct option options[] = {{"help", 0, NULL, 1000}, {0,0,0,0}};
    int ch;
    while ((ch = getopt_long(argc, argv, "acmhr:t:", options, NULL)) != -1) {
        switch (ch) {
        case 'a': access_only = true; break;
        case 'm': modify_only = true; break;
        case 'c': no_create = true; break;
        case 'h': no_follow = true; break;
        case 'r': reference = optarg; break;
        case 't': stamp = optarg; break;
        case 1000: usage(); return 0;
        default: usage(); return 1;
        }
    }
    if (optind == argc || (reference && stamp)) { usage(); return 1; }
    struct timespec times[2] = {{0, UTIME_NOW}, {0, UTIME_NOW}};
    if (reference) {
        struct stat st;
        if ((no_follow ? lstat(reference, &st) : stat(reference, &st)) < 0) {
            error_path("cannot stat", reference); return 1;
        }
        times[0] = st.st_atim; times[1] = st.st_mtim;
    }
    if (stamp) {
        if (timestamp(stamp, &times[0]) < 0) {
            fprintf(stderr, "%s: invalid timestamp '%s'\n", program, stamp); return 1;
        }
        times[1] = times[0];
    }
    if (access_only && !modify_only) times[1].tv_nsec = UTIME_OMIT;
    if (modify_only && !access_only) times[0].tv_nsec = UTIME_OMIT;
    int failed = 0;
    for (int i = optind; i < argc; ++i) {
        int flags = no_follow ? AT_SYMLINK_NOFOLLOW : 0;
        if (utimensat(AT_FDCWD, argv[i], times, flags) == 0) continue;
        if (errno == ENOENT && no_create) continue;
        if (errno == ENOENT && !no_follow) {
            int fd = open(argv[i], O_WRONLY | O_CREAT | O_NONBLOCK, 0666);
            if (fd < 0) { error_path("cannot create", argv[i]); failed = 1; continue; }
            int rc = futimens(fd, times);
            if (rc < 0) { error_path("cannot set timestamps", argv[i]); failed = 1; }
            if (close(fd) < 0) { error_path("cannot close", argv[i]); failed = 1; }
        } else { error_path("cannot set timestamps", argv[i]); failed = 1; }
    }
    return failed;
}
#include "common.h"
#include <errno.h>
#include <getopt.h>
#include <stdio.h>
#include <string.h>

static void usage(void) {
    printf("Usage: %s [-nbsvETAet] [FILE...]\n"
           "Concatenate files (or standard input for - or no files).\n"
           "  -n number lines  -b number nonblank lines  -s squeeze blank lines\n"
           "  -v show controls  -E show line ends  -T show tabs  -A all three\n", program);
}
int main(int argc, char **argv) {
    init_program(argv[0]);
    bool number = false, nonblank = false, squeeze = false;
    bool visible = false, ends = false, tabs = false;
    const struct option options[] = {{"help",0,NULL,1000},{0,0,0,0}};
    int ch;
    while ((ch = getopt_long(argc, argv, "nbsvETAetu", options, NULL)) != -1) {
        switch (ch) {
        case 'n': number = true; break;
        case 'b': nonblank = true; break;
        case 's': squeeze = true; break;
        case 'A': visible = ends = tabs = true; break;
        case 'e': visible = ends = true; break;
        case 't': visible = tabs = true; break;
        case 'v': visible = true; break;
        case 'E': ends = true; break;
        case 'T': tabs = true; break;
        case 'u': break;
        case 1000: usage(); return 0;
        default: usage(); return 1;
        }
    }
    unsigned long long line = 1;
    bool start = true, previous_blank = false, pending_cr = false;
    int failed = 0;
    int count = argc - optind;
    for (int i = 0; i < (count ? count : 1); ++i) {
        const char *path = count ? argv[optind + i] : "-";
        FILE *in = !strcmp(path, "-") ? stdin : fopen(path, "rb");
        if (!in) { error_path("cannot open", path); failed = 1; continue; }
        int c;
        while ((c = fgetc(in)) != EOF) {
            /* -E displays CRLF as ^M$, even without -v. Keep the CR pending
               across file boundaries because input files form one stream. */
            if (pending_cr) {
                if (c == '\n' || visible) fputs("^M", stdout);
                else putchar('\r');
                pending_cr = false;
            }
            if (start) {
                bool blank = c == '\n';
                if (squeeze && blank && previous_blank) continue;
                if ((nonblank && !blank) || (number && !nonblank)) printf("%6llu\t", line++);
                previous_blank = blank;
                start = false;
            }
            if (c == '\n') {
                if (ends) putchar('$');
                putchar('\n'); start = true;
            } else if (c == '\r' && ends) {
                pending_cr = true;
            } else if (c == '\t') {
                if (tabs) fputs("^I", stdout); else putchar(c);
            } else {
                if (visible && c >= 128) { fputs("M-", stdout); c -= 128; }
                if (visible && (c < 32 || c == 127)) {
                    putchar('^'); putchar(c == 127 ? '?' : c + 64);
                } else putchar(c);
            }
            if (ferror(stdout)) break;
        }
        if (ferror(in)) { error_path("cannot read", path); failed = 1; }
        if (in != stdin && fclose(in) != 0) { error_path("cannot close", path); failed = 1; }
        if (ferror(stdout)) break;
    }
    if (pending_cr) {
        if (visible) fputs("^M", stdout); else putchar('\r');
    }
    if (fflush(stdout) == EOF || ferror(stdout)) { error_path("cannot write", "standard output"); failed = 1; }
    return failed;
}
#include "common.h"
#include <errno.h>
#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static void usage(void) {
    printf("Usage: %s [-pv] [-m OCTAL_MODE] DIRECTORY...\n"
           "  -p create parents, accept existing directories  -v report creations\n", program);
}
static int create(const char *path, mode_t mode, bool parents, bool verbose) {
    if (mkdir(path, mode) == 0) {
        if (verbose) printf("created directory '%s'\n", path);
        return 1;
    }
    if (parents && errno == EEXIST) {
        struct stat st;
        if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) return 0;
        errno = EEXIST;
    }
    error_path("cannot create directory", path);
    return -1;
}
int main(int argc, char **argv) {
    init_program(argv[0]);
    bool parents = false, verbose = false, explicit_mode = false;
    mode_t mask = umask(0); umask(mask);
    mode_t mode = 0777 & ~mask;
    const struct option options[] = {{"help",0,NULL,1000},{0,0,0,0}};
    int ch;
    while ((ch = getopt_long(argc, argv, "pvm:", options, NULL)) != -1) {
        switch (ch) {
        case 'p': parents = true; break;
        case 'v': verbose = true; break;
        case 'm':
            explicit_mode = true;
            if (parse_mode(optarg, &mode) < 0) {
                fprintf(stderr, "%s: invalid mode '%s'\n", program, optarg); return 1;
            }
            break;
        case 1000: usage(); return 0;
        default: usage(); return 1;
        }
    }
    if (optind == argc) { usage(); return 1; }
    int failed = 0;
    for (int i = optind; i < argc; ++i) {
        char *path = clean_path(argv[i]);
        bool ok = true;
        if (parents) {
            for (char *p = path + (*path == '/' ? 1 : 0); *p; ++p) {
                if (*p != '/' || p == path || p[-1] == '/') continue;
                *p = '\0';
                /* Parent directories must remain traversable even under a restrictive umask. */
                mode_t parent_mode = (0777 & ~mask) | S_IWUSR | S_IXUSR;
                mode_t previous = umask(0);
                int rc = create(path, parent_mode, true, verbose);
                umask(previous);
                *p = '/';
                if (rc < 0) { ok = false; break; }
            }
        }
        if (ok) {
            int rc = create(path, mode, parents, verbose);
            if (rc < 0) failed = 1;
            else if (rc > 0 && explicit_mode && chmod(path, mode) < 0) {
                error_path("cannot set mode", path); failed = 1;
            }
        } else failed = 1;
        free(path);
    }
    return failed;
}
#include "common.h"
#include <errno.h>
#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static void usage(void) {
    printf("Usage: %s [-finvT] SOURCE... DESTINATION\n"
           "  -f overwrite  -i prompt before overwrite  -n no overwrite\n"
           "  -v report moves  -T treat destination as a file\n", program);
}
static int move_one(const char *source, const char *target, bool interactive, bool no_clobber, bool verbose) {
    struct stat src, dst;
    if (lstat(source, &src) < 0) { error_path("cannot stat", source); return -1; }
    int exists = lstat(target, &dst) == 0;
    if (!exists && errno != ENOENT) { error_path("cannot stat", target); return -1; }
    if (exists) {
        if (src.st_dev == dst.st_dev && src.st_ino == dst.st_ino) {
            fprintf(stderr, "%s: '%s' and '%s' are the same file\n", program, source, target); return -1;
        }
        if (no_clobber || (interactive && !confirm("overwrite", target))) return 0;
    }
    if (rename(source, target) == 0) {
        if (verbose) printf("'%s' -> '%s'\n", source, target);
        return 0;
    }
    if (errno != EXDEV) { error_path("cannot move to", target); return -1; }
    if (exists) {
        if (S_ISDIR(src.st_mode) != S_ISDIR(dst.st_mode)) {
            errno = S_ISDIR(dst.st_mode) ? EISDIR : ENOTDIR;
            error_path("cannot replace", target); return -1;
        }
    }
    /* Stage beside the target, so a failed copy cannot destroy an existing target. */
    char *parent = xstrdup(target);
    char *slash = strrchr(parent, '/');
    if (slash) { if (slash == parent) slash[1] = '\0'; else *slash = '\0'; }
    else { free(parent); parent = xstrdup("."); }
    char *temporary = join_path(parent, ".fileutils-mv-XXXXXX");
    free(parent);
    if (!mkdtemp(temporary)) { error_path("cannot create staging directory", temporary); free(temporary); return -1; }
    char *staged = join_path(temporary, "content");
    int rc = copy_tree(source, staged);
    if (rc == 0 && rename(staged, target) < 0) { error_path("cannot replace", target); rc = -1; }
    if (rc == 0) rc = remove_tree(source, true, true, false, false, false);
    if (remove_tree(temporary, true, true, false, false, false) < 0) rc = -1;
    if (rc == 0 && verbose) printf("'%s' -> '%s'\n", source, target);
    free(staged); free(temporary);
    return rc;
}
int main(int argc, char **argv) {
    init_program(argv[0]);
    bool interactive = false, no_clobber = false, verbose = false, no_target_dir = false;
    const struct option options[] = {{"help",0,NULL,1000},{0,0,0,0}};
    int ch;
    while ((ch = getopt_long(argc, argv, "finvT", options, NULL)) != -1) {
        switch (ch) {
        case 'f': interactive = no_clobber = false; break;
        case 'i': interactive = true; no_clobber = false; break;
        case 'n': no_clobber = true; interactive = false; break;
        case 'v': verbose = true; break;
        case 'T': no_target_dir = true; break;
        case 1000: usage(); return 0;
        default: usage(); return 1;
        }
    }
    if (argc - optind < 2) { usage(); return 1; }
    char *destination = clean_path(argv[argc - 1]);
    struct stat st;
    bool target_dir = !no_target_dir && stat(destination, &st) == 0 && S_ISDIR(st.st_mode);
    if (argc - optind > 2 && !target_dir) {
        fprintf(stderr, "%s: destination must be a directory\n", program); free(destination); return 1;
    }
    int failed = 0;
    for (int i = optind; i < argc - 1; ++i) {
        char *source = clean_path(argv[i]);
        char *target = target_dir ? join_path(destination, base_name(source)) : xstrdup(destination);
        if (move_one(source, target, interactive, no_clobber, verbose) < 0) failed = 1;
        free(source); free(target);
    }
    free(destination);
    return failed;
}
#include "common.h"
#include <errno.h>
#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void usage(void) {
    printf("Usage: %s [-firdRv] FILE...\n"
           "  -r, -R recursive  -d empty directories  -f ignore missing, never prompt\n"
           "  -i prompt before removal  -v report removals\n", program);
}
int main(int argc, char **argv) {
    init_program(argv[0]);
    bool recursive = false, dirs = false, force = false, interactive = false, verbose = false;
    const struct option options[] = {{"help",0,NULL,1000},{0,0,0,0}};
    int ch;
    while ((ch = getopt_long(argc, argv, "firdRv", options, NULL)) != -1) {
        switch (ch) {
        case 'f': force = true; interactive = false; break;
        case 'i': interactive = true; force = false; break;
        case 'r': case 'R': recursive = true; break;
        case 'd': dirs = true; break;
        case 'v': verbose = true; break;
        case 1000: usage(); return 0;
        default: usage(); return 1;
        }
    }
    if (optind == argc) { if (force) return 0; usage(); return 1; }
    int failed = 0;
    struct stat root;
    if (stat("/", &root) < 0) { error_path("cannot stat", "/"); return 1; }
    for (int i = optind; i < argc; ++i) {
        char *path = clean_path(argv[i]);
        const char *base = base_name(path);
        struct stat st;
        bool dot = !strcmp(base, ".") || !strcmp(base, "..");
        bool is_root = lstat(path, &st) == 0 && S_ISDIR(st.st_mode) &&
                       st.st_dev == root.st_dev && st.st_ino == root.st_ino;
        if (dot || is_root) {
            fprintf(stderr, "%s: refusing to remove '%s'\n", program, argv[i]); failed = 1;
        } else if (remove_tree(path, recursive, dirs, force, interactive, verbose) < 0) failed = 1;
        free(path);
    }
    return failed;
}
#include "common.h"
#include <dirent.h>
#include <errno.h>
#include <fnmatch.h>
#include <getopt.h>
#include <limits.h>
