static Node *parse_and(void) {
    Node *n = parse_unary();
    while (position < count && strcmp(args[position], ")") &&
           strcmp(args[position], "-o") && strcmp(args[position], "-or")) {
        if (!strcmp(args[position], "-a") || !strcmp(args[position], "-and")) ++position;
        Node *right = parse_unary();
        n = node(AND, n, right);
    }
    return n;
}
static Node *parse_or(void) {
    Node *n = parse_and();
    while (position < count && (!strcmp(args[position], "-o") || !strcmp(args[position], "-or"))) {
        ++position;
        Node *right = parse_and();
        n = node(OR, n, right);
    }
    return n;
}
